const $=s=>document.querySelector(s),root=$('#workspace-app');
let chapters=[],bank=[],translations={},chapterTranslations={},examTranslations={},sectionTranslations={};
const params=new URLSearchParams(location.search);let view=params.get('view')||document.body.dataset.initialView||'home',selected=Number(params.get('chapter'))||19,query='',group='all',quiz=null,lab=null,labId=params.get('task')||null,labTab='map',user=null,syncStatus='guest',authMode='login',authMessage='',recoverySecret=null,recoveryWasReset=false,accountBusy=false,readerStatus='',bookPage=Number(params.get('page'))||0,bookRestoring=false;
let animateNext=true,sphere=null,mapEdgeId='acid-chloride';
let data=readLocal('guest');
try{if(!localStorage.getItem('or-v3-progress:guest')){const old=JSON.parse(localStorage.getItem('or-progress-v1'));if(old?.history)for(const [i,h]of old.history.entries())data.sessions['legacy-'+i]={chapter:h.chapter,correct:h.correct,total:h.total,at:Date.parse(h.date)||1}}}catch{}
const L=s=>language()==='en'?s:examTranslations[s]?.[language()]||s;
const title=c=>chapterTitle(c,chapterTranslations),chapter=()=>chapters.find(c=>c.id===selected)||chapters[18];
const icons={home:'<path d="m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',lab:'<path d="M9 3h6M10 3v7L4 20q-1 2 2 2h12q3 0 2-2l-6-10V3M8 16h8"/>',book:'<path d="M12 5v16M3 3q5-1 9 2 4-3 9-2v16q-5-1-9 2-4-3-9-2Z"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',chart:'<path d="M4 3v18h17M8 15v3M13 10v8M18 5v13"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
function toast(text){$('#app-toast').textContent=text;$('#app-toast').className='show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#app-toast').className='',5000)}
function save(){data.updated=Date.now();if(!writeLocal(user?.id||'guest',data))toast(pick('Browser storage is unavailable. Export a backup.','浏览器存储不可用，请导出备份。','Stockage indisponible. Exportez une sauvegarde.'));account.queue(data);updateSaveBadge()}
function updateSaveBadge(){document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=user?t(syncStatus==='error'?'syncError':syncStatus==='syncing'?'syncing':'synced'):t('saved'))}
const account=new Account({onUser:(u,d)=>{user=u;data=d;if(d.notes?.preferences?.language)setLanguage(d.notes.preferences.language);quiz=null;labId=null;syncStatus=u?'syncing':'guest';if(chapters.length){if(view==='account'&&u){view='home';animateNext=true;}render()}},onRemote:d=>{const previousLanguage=language();data=mergeProgress(data,d);if(user&&data.notes?.preferences?.language)setLanguage(data.notes.preferences.language);if(previousLanguage!==language()){render();return}if((view==='progress'||view==='home')&&!labId)render();updateSaveBadge()},onSync:s=>{syncStatus=s;updateSaveBadge()}});
const book=new TextbookReader({onStatus:s=>{readerStatus=s;const status=$('#reader-status');if(status)status.textContent=s==='ready'?'':t(s);const region=$('.reader-main');if(region)region.setAttribute('aria-busy',String(s==='reading'))},onPage:p=>{bookPage=p;if(view==='reader'){const visibleChapter=chapters.find(c=>p>=c.start&&p<=c.end);if(visibleChapter&&visibleChapter.id!==selected){selected=visibleChapter.id;const contents=$('.reader-contents');if(contents)contents.innerHTML=readerContents(visibleChapter);const select=$('#reader-chapter');if(select)select.value=String(selected)}const url=new URL(location.href);url.searchParams.set('chapter',selected);url.searchParams.set('page',p);history.replaceState(null,'',url)}{data.bookmarks['last-'+selected]={page:p,chapter:selected,at:Date.now()};save()}const input=$('#book-page');if(input)input.value=p;const n=$('#book-total');if(n)n.textContent='/ '+book.totalPages}});
function route(v,{chapter:n,page:p,lab:id}={}){if(recoverySecret&&v!=='account'){toast(t('saveRecoveryFirst'));return}if(n&&chapters.some(c=>c.id===+n))selected=+n;if(p)bookPage=+p;if(id!==undefined)labId=id;else if(v!=='visual')labId=null;view=v;animateNext=true;const url=new URL(location.href);url.pathname=url.pathname.replace(/(?:practice|review)\.html$/,'index.html');url.searchParams.set('view',v);url.searchParams.set('chapter',selected);if(v==='visual'&&labId)url.searchParams.set('task',labId);else url.searchParams.delete('task');if(p)url.searchParams.set('page',p);else url.searchParams.delete('page');history.pushState(null,'',url);render();window.scrollTo({top:0,behavior:'instant'});$('#content')?.focus({preventScroll:true})}
function shell(content,{hero=false}={}){sphere?.destroy();sphere=null;const nav=[['home','home','home'],['chapters','chapters','grid'],['visual','visual','lab'],['reader','reader','book'],['progress','progress','chart']];root.innerHTML=`<header class="site-header"><a class="wordmark" href="./index.html" aria-label="Organic Recall"><svg viewBox="0 0 36 40" fill="none" stroke="currentColor" stroke-width="1.3"><path d="M18 2 34 11v18l-16 9L2 29V11Z"/><path d="m18 9 10 6v10l-10 6-10-6V15Z"/></svg><span>ORGANIC<span class="brand-light">/RECALL</span></span></a><nav aria-label="${t('chapters')}">${nav.map(([id,label])=>`<button data-view="${id}" class="${view===id||id==='chapters'&&view==='chapter'||id==='chapters'&&view==='quiz'?'active':''}">${t(label)}</button>`).join('')}</nav><div class="header-right"><button class="icon-button settings-trigger" data-view="settings" aria-label="${t('settings')}">${icon('settings')}</button><button class="account-button" data-view="account">${user?esc(user.username):t('login')} ${icon('user')}</button></div></header><main id="content" class="${hero?'landing':'inner-page'}" tabindex="-1">${content}</main><footer class="site-footer"><a class="footer-wordmark" href="./index.html">ORGANIC/RECALL</a><span>EN / 中文 / FR</span></footer><nav class="mobile-navigation" aria-label="${t('home')}">${nav.map(([v,label,i])=>`<button data-view="${v}" class="${view===v?'active':''}">${icon(i)}<span>${t(label)}</span></button>`).join('')}</nav>`;document.title='Organic Recall · '+t(view==='chapter'?'chapters':view==='quiz'?'start':view);document.body.dataset.view=view;const skip=$('.skip');if(skip)skip.textContent=pick('Skip to content','跳至主要内容','Aller au contenu');updateSaveBadge();enterWorkspace()}
function enterWorkspace(){if(!animateNext)return;animateNext=false;if(document.body.classList.contains('reduce-motion')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const main=$('#content');if(!main?.animate)return;main.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,.7,.2,1)'});main?.querySelectorAll('.chapter-tile,.quick-action,.visual-tile').forEach((card,i)=>card.animate([{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:280,delay:Math.min(i,6)*20,easing:'cubic-bezier(.2,.7,.2,1)',fill:'backwards'}))}
function chapterSelect(id='chapter-select'){return `<label class="field"><span>${t('choose')}</span><select id="${id}" data-chapter-select aria-label="${t('choose')}">${chapters.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${String(c.id).padStart(2,'0')} · ${esc(title(c))}</option>`).join('')}</select></label>`}
function chapterSphereDetail(){const c=chapter(),draft=data.notes['quiz-draft']?.quiz?.chapter===c.id;return `<div class="dock-copy"><span class="dock-number">${String(c.id).padStart(2,'0')}</span><h2>${esc(title(c))}</h2></div><div class="dock-actions"><button class="solid-button" data-action="${draft?'resume-quiz':'open-chapter'}">${draft?t('continue'):t('start')} ${icon('arrow')}</button><button class="icon-button dock-icon" data-read-chapter="${c.id}" aria-label="${t('reader')}" title="${t('reader')}">${icon('book')}</button></div>`}
function selectSphereChapter(id){selected=+id;const list=$('#chapter-list');if(list)list.open=false;const url=new URL(location.href);url.searchParams.set('chapter',selected);history.replaceState(null,'',url);const target=$('#sphere-chapter-detail');if(target)target.innerHTML=chapterSphereDetail();const select=$('#hero-chapter');if(select)select.value=String(id);sphere?.select(id)}
function landing(){shell(`<section class="immersive-navigator"><div class="immersive-heading"><h1>${t('chapters')}</h1><details class="sphere-list compact-list" id="chapter-list"><summary role="button" aria-label="${t('choose')}" title="${t('choose')}">☷</summary><div>${chapterSelect('hero-chapter')}<button class="text-button" data-view="chapters">${t('allChapters')} ↗</button></div></details></div><div id="chapter-sphere"></div><div id="sphere-chapter-detail" class="selection-dock">${chapterSphereDetail()}</div></section>`);sphere=new ParticleSphere($('#chapter-sphere'),{items:chapters.map(c=>({id:c.id,label:String(c.id).padStart(2,'0'),title:title(c),accessible:t('chapter')+' '+c.id+' · '+title(c),group:c.group})),active:selected,onSelect:selectSphereChapter})}
function chapterCards(){return chapters.filter(c=>(group==='all'||c.group===Number(group))&&(!query||`${c.id} ${c.title} ${title(c)}`.toLowerCase().includes(query.toLowerCase()))).map(c=>`<article class="chapter-tile"><div class="tile-top"><span class="mono">${String(c.id).padStart(2,'0')}</span>${c.id===19?`<span class="pill">${t('visualReady')}</span>`:''}</div><h2>${esc(title(c))}</h2><p>${bank.filter(q=>q.chapter===c.id).length} ${t('questions')} <span>PDF ${c.start}–${c.end}</span></p><div class="tile-bottom"><button class="text-button" data-open-chapter="${c.id}">${t('open')} ↗</button><button class="icon-button" data-read-chapter="${c.id}" aria-label="${t('openBook')} ${c.id}">${icon('book')}</button></div></article>`).join('')}
function renderChapters(){shell(`<div class="page-heading"><span class="eyebrow">THE COURSE / 26</span><h1>${t('allChapters')}</h1></div><div class="catalogue-toolbar"><input id="chapter-search" type="search" value="${esc(query)}" placeholder="${t('search')}" aria-label="${t('search')}"><div class="filter-tabs">${[['all','all'],[0,'foundations'],[1,'reactions'],[2,'carbonyls'],[3,'bio']].map(([id,label])=>`<button data-group="${id}" class="${String(group)===String(id)?'active':''}">${t(label)}</button>`).join('')}</div></div><div class="chapter-grid" id="chapter-grid">${chapterCards()}</div>`)}
function renderChapter(){const c=chapter(),list=bank.filter(q=>q.chapter===selected),stats=Object.values(data.answers).filter(a=>list.some(q=>q.id===a.id));shell(`<button class="text-button" data-view="chapters">← ${t('backChapters')}</button><section class="chapter-heading"><span class="eyebrow">${t('chapter')} ${String(c.id).padStart(2,'0')} / VOLLHARDT & SCHORE</span><h1>${esc(title(c))}</h1><p>${list.length} ${t('questions')} · ${t('page')} ${c.start}–${c.end}</p></section><div class="chapter-layout"><section class="panel course-panel"><div class="section-top"><h2>${t('questionTypes')}</h2>${chapterSelect()}</div><div class="type-choices">${['Products','Reagents','Mechanisms','Synthesis','Concepts'].map(k=>`<label><input type="checkbox" name="question-type" value="${k}" checked><span>${t(k)}</span></label>`).join('')}</div><label class="field count-field"><span>${t('questionCount')}</span><select id="question-count"><option>5</option><option selected>8</option><option>12</option></select></label><button class="solid-button" data-action="start-quiz">${t('start')} ${icon('arrow')}</button><details class="study-details"><summary>${pick('About this practice','练习说明','À propos des exercices')}</summary><p>${t('courseNote')}</p></details></section><aside><section class="panel mini-panel"><span class="eyebrow">${t('reader')}</span><h2>${t('bookIntro')}</h2><button class="outline-button" data-read-chapter="${c.id}">${t('openBook')} ↗</button></section>${c.id===19?`<section class="panel mini-panel violet-wash"><span class="eyebrow">${t('visual')}</span><h2>${t('simpleVisual')}</h2><button class="outline-button" data-view="visual">${t('openLab')} ↗</button></section>`:''}</aside></div>`)}
function startQuiz(){const focus=[...document.querySelectorAll('[name="question-type"]:checked')].map(n=>n.value);const allowed=focus.length?focus:['Products','Reagents','Mechanisms','Synthesis','Concepts'];if(view==='chapter'&&!focus.length){toast(t('noQuestions'));return}const count=Number($('#question-count')?.value)||8;const pool=bank.filter(q=>q.chapter===selected&&allowed.includes(q.type));const ids=pool.map(q=>q.id);for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}quiz={chapter:selected,ids:ids.slice(0,count),index:0,answers:{},checked:{},orders:{},started:Date.now()};for(const id of quiz.ids){const order=[0,1,2,3];for(let i=3;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]]}quiz.orders[id]=order}if(!quiz.ids.length){toast(t('noQuestions'));return}saveQuizDraft();route('quiz')}
function saveQuizDraft(){data.notes['quiz-draft']={quiz:quiz?structuredClone(quiz):null,at:Date.now()};save()}
function renderQuiz(){if(!quiz){const draft=data.notes['quiz-draft']?.quiz;if(draft?.ids?.length&&draft.answers&&draft.checked&&chapters.some(c=>c.id===draft.chapter)&&draft.ids.every(id=>bank.some(q=>q.id===id))&&Number.isInteger(draft.index)&&draft.index>=0&&draft.index<draft.ids.length){quiz=structuredClone(draft);selected=quiz.chapter}else{route('chapter');return}}const original=bank.find(q=>q.id===quiz.ids[quiz.index]),q=translatedQuestion(original,translations),answer=quiz.answers[q.id],checked=quiz.checked[q.id];shell(`<div class="quiz-top"><button class="text-button" data-view="chapter">← ${t('back')}</button><span>${t('chapter')} ${quiz.chapter} / ${esc(title(chapters.find(c=>c.id===quiz.chapter)))}</span><span class="mono">${String(quiz.index+1).padStart(2,'0')} / ${quiz.ids.length}</span></div><div class="quiz-progress"><i style="width:${100*quiz.index/quiz.ids.length}%"></i></div><section class="quiz-card"><div class="question-meta"><span class="pill">${t(q.type)}</span><span>${esc(q.topic)}</span></div><h1>${esc(q.prompt)}</h1><div class="answer-options">${(quiz.orders?.[q.id]||[0,1,2,3]).map((i,j)=>`<button data-option="${i}" aria-pressed="${answer===i}" class="${answer===i?'selected ':''}${checked&&i===q.answer?'correct ':''}${checked&&answer===i&&i!==q.answer?'incorrect':''}" ${checked?'disabled':''}><span>${'ABCD'[j]}</span>${esc(q.options[i])}</button>`).join('')}</div>${checked?`<aside class="question-explanation" role="status"><h3>${answer===q.answer?t('correct'):t('tryAgain')}</h3><p>${esc(q.explanation)}</p><div class="reference-line">${t('source')} · §${q.section} ${q.pages.map(p=>`<button class="text-button" data-read-page="${p}">${t('page')} ${p} ↗</button>`).join('')}</div></aside>`:''}<div class="quiz-controls"><span data-sync-status></span><button class="solid-button" data-action="${checked?'next-question':'check-question'}" ${!checked&&answer===undefined?'disabled':''}>${checked?(quiz.index===quiz.ids.length-1?t('finish'):t('next')):t('check')} →</button></div></section>`)}
function checkQuestion(){const q=bank.find(q=>q.id===quiz.ids[quiz.index]);const answer=quiz.answers[q.id];if(answer===undefined)return;quiz.checked[q.id]=true;data.answers[q.id]={id:q.id,chapter:q.chapter,answer,correct:answer===q.answer,at:Date.now()};saveQuizDraft();renderQuiz();$('[data-action=next-question]')?.focus({preventScroll:true})}
function nextQuestion(){if(quiz.index<quiz.ids.length-1){quiz.index++;saveQuizDraft();animateNext=true;renderQuiz();window.scrollTo(0,0);$('#content')?.focus({preventScroll:true})}else{const correct=quiz.ids.filter(id=>quiz.answers[id]===bank.find(q=>q.id===id).answer).length;data.sessions['session-'+quiz.started]={chapter:quiz.chapter,total:quiz.ids.length,correct,at:Date.now()};data.notes['quiz-draft']={quiz:null,at:Date.now()};save();shell(`<div class="result-panel"><span class="eyebrow">RECALL / COMPLETE</span><h1>${t('result')}</h1><div class="result-score">${correct}<span>/ ${quiz.ids.length}</span></div><p>${t('accuracy')} · ${Math.round(100*correct/quiz.ids.length)}%</p><div class="button-row"><button class="solid-button" data-view="chapter">${t('start')} ↗</button><button class="outline-button" data-view="progress">${t('progress')} ↗</button></div></div>`);window.scrollTo(0,0)}}
function visualCard(q){const r=data.visual[q.id];return `<button class="visual-tile" data-lab-id="${q.id}"><span class="mono">${q.number} / ${L(q.topic)}</span><div class="tile-structure">${q.source?moleculeSVG(q.source):q.steps?moleculeSVG(q.steps[0].source):'<span>CH3CH2MgBr →</span>'}</div><h2>${L(q.title)}</h2><span class="tile-status">${r?.completed?'✓ '+pick('Completed','已完成','Terminé'):r?.needsReview?t('weak'):t('start')} ↗</span></button>`}
function reactionDetail(id){const edge=edges.find(e=>e.id===id)||edges[4],from=networkNodes.find(n=>n.id===edge.from),to=networkNodes.find(n=>n.id===edge.to),q=visualQuestions.find(q=>q.id===edge.task);return `<div class="dock-copy"><span class="dock-label">${L(edge.short)}</span><h2>${esc(from.label)} <span class="reaction-detail-arrow">→</span> ${esc(to.label)}</h2></div><div class="dock-actions">${q?'<button class="solid-button" data-lab-id="'+q.id+'">'+t('start')+' ↗</button>':''}<button class="outline-button" data-reveal-edge="${edge.id}" aria-expanded="false">${pick('Conditions','反应条件','Conditions')}</button><button class="icon-button dock-icon" data-read-page="${edge.refs[0]}" aria-label="${t('reader')}" title="${t('reader')}">${icon('book')}</button></div><div class="edge-answer"></div>`}
function selectReaction(id){if(!edges.some(e=>e.id===id))return;mapEdgeId=id;sphere?.select(id);const select=$('#reaction-select');if(select)select.value=id;const detail=$('#edge-detail');if(detail)detail.innerHTML=reactionDetail(id)}
function mapMarkup(){return `<section class="immersive-navigator reaction-navigator"><div id="reaction-sphere"></div><div class="reaction-dock-row"><aside id="edge-detail" class="selection-dock" aria-live="polite">${reactionDetail(mapEdgeId)}</aside><details class="sphere-list compact-list reaction-list-picker"><summary role="button" aria-label="${pick('Choose a reaction','选择反应','Choisir une réaction')}" title="${pick('Choose a reaction','选择反应','Choisir une réaction')}">☷</summary><div><select id="reaction-select" aria-label="${pick('Choose a reaction','选择反应','Choisir une réaction')}">${edges.map(e=>'<option value="'+e.id+'" '+(e.id===mapEdgeId?'selected':'')+'>'+L(e.short)+'</option>').join('')}</select></div></details></div></section>`}
function mountReactionSphere(){const links=[];edges.forEach((a,i)=>edges.forEach((b,j)=>{if(i!==j&&a.to===b.from)links.push([i,j])}));sphere=new ParticleSphere($('#reaction-sphere'),{kind:'reactions',items:edges.map((e,i)=>({id:e.id,label:String(i+1).padStart(2,'0'),title:L(e.short),accessible:L(e.short)+' · '+networkNodes.find(n=>n.id===e.from).label+' → '+networkNodes.find(n=>n.id===e.to).label,group:e.task?1:0})),links,active:mapEdgeId,onSelect:selectReaction})}
function renderVisual(){if(labId){const q=visualQuestions.find(q=>q.id===labId);if(q){shell('<div id="guided-lab"></div>');lab=new VisualLab($('#guided-lab'),{question:q,record:data.visual[q.id],translate:L,onSave:r=>{data.visual[q.id]=r;save()},onBack:()=>{labId=null;route('visual')},onRead:p=>route('reader',{page:p})});return}labId=null}const other=selected!==19;shell(`<div class="page-heading lab-page-heading"><h1>${t('visual')}</h1>${chapterSelect('lab-chapter')}</div>${other?'<section class="panel empty-state"><h2>'+esc(title(chapter()))+'</h2><p>'+t('visualOther')+'</p><div class="button-row"><button class="solid-button" data-view="chapter">'+t('start')+'</button><button class="outline-button" data-switch-lab="19">'+t('visualScope')+' →</button></div></section>':`<div class="visual-tabs"><button data-lab-tab="map" class="${labTab==='map'?'active':''}">${pick('Reaction map','反应网络','Carte des réactions')}</button><button data-lab-tab="integrated" class="${labTab==='integrated'?'active':''}">${pick('Integrated practice','综合练习','Exercices intégrés')}</button></div>${labTab==='map'?mapMarkup():integrated.map((p,i)=>`<details class="integrated-problem"><summary><span class="mono">0${i+1}</span><h2>${L(p.title)}</h2><span>＋</span></summary><div><p>${L(p.prompt)}</p><label class="field"><span>${pick('Your route / reasoning','你的路线与思路','Votre démarche')}</span><textarea maxlength="20000" data-note="${p.id}">${esc(data.notes[p.id]?.text||'')}</textarea></label><div class="button-row">${p.tasks.map(id=>'<button class="outline-button" data-lab-id="'+id+'">'+L(visualQuestions.find(q=>q.id===id).topic)+' ↗</button>').join('')}</div><details class="self-check"><summary>${t('reveal')}</summary><ul>${p.checks.map(c=>'<li>'+L(c)+'</li>').join('')}</ul></details></div></details>`).join('')}`}`);if(!other&&labTab==='map')mountReactionSphere()}

function readerContents(c){return `<div class="contents-heading"><span class="mono">${String(c.id).padStart(2,'0')}</span><h2>${esc(title(c))}</h2></div><button class="contents-page" data-read-page="${c.start}">${t('chapter')} ${c.id}<span>${c.start}</span></button>${c.sections.map(s=>'<button class="contents-page" data-read-page="'+s.page+'"><span>§'+s.id+' '+esc(language()==='en'?s.title:sectionTranslations[s.id]?.[language()]||s.title)+'</span><small>'+s.page+'</small></button>').join('')}<button class="contents-page" data-read-page="${c.problems}">${pick('End-of-chapter problems','章末习题','Exercices de fin de chapitre')}<small>${c.problems}</small></button>`}
function renderReader(){const c=chapter();if(!bookPage)bookPage=data.bookmarks['last-'+selected]?.page||c.start;shell(`<div class="page-heading reader-heading"><div><h1>${t('reader')}</h1><p>Organic Chemistry · 6th edition</p></div>${chapterSelect('reader-chapter')}</div><div class="reader-layout"><aside class="reader-contents">${readerContents(c)}</aside><section class="reader-main"><div class="reader-toolbar"><button class="icon-button" data-action="prev-page" aria-label="${t('prevPage')}">←</button><label>${t('page')} <input id="book-page" type="number" min="1" max="1374" value="${bookPage}" aria-label="${t('page')}"></label><span id="book-total">/ 1374</span><button class="icon-button" data-action="next-page" aria-label="${t('nextPage')}">→</button><button class="text-button" data-action="go-page">${t('go')}</button><select id="book-zoom" aria-label="${t('zoom')}"><option value=".8" ${book.zoom===.8?'selected':''}>80%</option><option value="1" ${book.zoom===1?'selected':''}>100%</option><option value="1.25" ${book.zoom===1.25?'selected':''}>125%</option></select><button class="icon-button" data-action="bookmark" aria-label="${t('bookmark')}">☆</button></div><div class="reader-canvas-wrap"><canvas id="textbook-canvas" role="img"></canvas></div><div class="reader-status-row"><p id="reader-status" class="quiet-note" role="status"></p><button class="text-button" data-action="reader-retry">${pick('Reload page','重新加载','Recharger')}</button></div></section></div>`);book.attach($('#textbook-canvas'),bookPage)}

function renderProgress(){const s=progressStats(data),sessions=Object.values(data.sessions).sort((a,b)=>b.at-a.at);shell(`<div class="page-heading"><span class="eyebrow">YOUR CONNECTIONS</span><h1>${t('progress')}</h1>${user?'<p>'+esc(user.username)+'</p>':''}</div><div class="progress-stats"><div><strong>${s.answered}</strong><span>${t('answered')}</span></div><div><strong>${s.answered?Math.round(s.correct*100/s.answered)+'%':'—'}</strong><span>${t('accuracy')}</span></div><div><strong>${s.weak}</strong><span>${t('weak')}</span></div></div><div class="progress-layout"><section>${data.notes['quiz-draft']?.quiz?`<button class="outline-button resume-quiz" data-action="resume-quiz">${t('continue')} →</button>`:''}<h2>${t('recent')}</h2>${sessions.length?sessions.slice(0,20).map(s=>`<button class="session-row" data-open-chapter="${s.chapter}"><span>${t('chapter')} ${s.chapter}<small>${new Date(s.at).toLocaleDateString(language()==='zh'?'zh-CN':language()==='fr'?'fr-FR':'en-GB')}</small></span><strong>${s.correct} / ${s.total}</strong><span>↗</span></button>`).join(''):`<div class="panel empty-state">${t('emptyProgress')}</div>`}<h2 class="spaced-title">${t('weak')}</h2><div class="weak-list">${Object.entries(data.answers).filter(([,a])=>!a.correct).slice(0,20).map(([id])=>{const q=bank.find(q=>q.id===id);if(!q)return '';return `<button data-review-question="${id}">${esc(translatedQuestion(q,translations).topic)} ↗</button>`}).join('')}${Object.entries(data.visual).filter(([,r])=>r.needsReview).map(([id])=>`<button ${id.startsWith('edge-')?`data-weak-edge="${id.slice(5)}"`:`data-lab-id="${id}"`}>${L(visualQuestions.find(q=>q.id===id)?.topic||id)} ↗</button>`).join('')}</div></section><aside class="panel account-summary"><h2>${t('account')}</h2><p>${user?esc(user.username):t('guest')}</p><p data-sync-status></p><button class="outline-button" data-action="export-progress">${t('export')} ↗</button>${user?`<button class="text-button" data-action="sync">${t('syncNow')}</button><p>${t('guestImportBody')}</p><button class="text-button" data-action="import-guest">${t('guestImport')}</button>`:`<button class="solid-button" data-view="account">${t('login')} ↗</button>`}</aside></div>`)}
function renderSettings(){shell(`<div class="page-heading"><span class="eyebrow">YOUR WORKSPACE</span><h1>${t('settings')}</h1></div><div class="settings-grid"><section class="panel"><h2>${t('language')}</h2><div class="language-options">${Object.entries(languages).map(([id,label])=>`<button data-language="${id}" class="${language()===id?'active':''}" aria-pressed="${language()===id}">${label}<span>${language()===id?'✓':''}</span></button>`).join('')}</div><label class="toggle-field"><span>${t('motion')}</span><input id="reduce-motion" type="checkbox" ${document.body.classList.contains('reduce-motion')?'checked':''}></label></section><section class="panel"><h2>${t('account')}</h2><p>${user?esc(user.username):t('guestBody')}</p><div class="button-row"><button class="outline-button" data-view="account">${t('account')} ↗</button><button class="text-button" data-action="export-progress">${t('export')}</button><button class="text-button" data-action="restore-progress">${t('import')}</button></div></section></div>`)}
function renderAccount(){const reset=authMode==='reset',signup=authMode==='signup';shell(`<section class="auth-layout"><div class="auth-editorial"><span class="eyebrow">ORGANIC / RECALL</span><h1>${pick('Your next<br><em>connection.</em>','下一次<br><em>知识的连接。</em>','Votre prochain<br><em>lien.</em>')}</h1><p>${pick('A little practice. A stronger bond.','每一次练习，都让记忆更牢固。','Un peu de pratique. Des liens plus solides.')}</p></div><div class="auth-panel panel"><h2>${t(recoverySecret?'recoveryHeading':reset?'recoverAccount':signup?'signup':'login')}</h2>${recoverySecret?`<p>${t(recoveryWasReset?'recoveryRotated':'recoveryBody')}</p><pre class="recovery-code">${esc(recoverySecret)}</pre><div class="button-row"><button class="outline-button" data-action="copy-recovery">${t('copyCode')}</button><button class="outline-button" data-action="download-recovery">${t('downloadCode')}</button></div><button class="solid-button recovery-confirm" data-action="recovery-saved">${t('codeSaved')} →</button>`:user?`<p>${esc(user.username)}</p><p data-sync-status></p><p>${t('syncedPrivate')}</p><div class="button-row"><button class="solid-button" data-view="progress">${t('progress')} ↗</button><button class="outline-button" data-action="logout">${t('logout')}</button></div>`:`${!reset?`<div class="auth-tabs"><button data-auth-mode="login" class="${!signup?'active':''}">${t('login')}</button><button data-auth-mode="signup" class="${signup?'active':''}">${t('signup')}</button></div>`:'<p>'+t('recoverBody')+'</p>'}<form id="auth-form"><label class="field"><span>${t('username')}</span><input name="username" type="text" autocomplete="username" required minlength="3" maxlength="24" placeholder="organic_student" ${signup?'aria-describedby="username-rule"':''}></label>${reset?`<label class="field"><span>${t('recoveryCode')}</span><input name="recoveryCode" type="password" autocomplete="off" required maxlength="100"></label>`:''}<label class="field"><span>${t(signup||reset?'passwordNew':'password')}</span><input name="password" type="password" autocomplete="${signup||reset?'new-password':'current-password'}" minlength="${signup||reset?10:1}" maxlength="64" required></label>${signup||reset?`<label class="field"><span>${t('passwordConfirm')}</span><input name="confirm" type="password" autocomplete="new-password" minlength="10" maxlength="64" required></label>`:''}${signup?'<p id="username-rule" class="quiet-note">'+t('usernameRule')+'</p>':''}<button class="solid-button auth-submit" type="submit" ${accountBusy||!account.ready||!account.config.registrationReady&&(signup||reset)?'disabled':''}>${t(reset?'recoverAccount':signup?'signup':'login')} →</button></form><p id="auth-message" role="status" class="auth-message">${authMessage}</p>${!account.ready||!account.config.registrationReady?`<p class="setup-note">${t('backendPending')}</p>`:''}<button class="text-button" data-auth-mode="${reset?'login':'reset'}">${reset?t('login'):t('forgot')}</button><button class="text-button" data-view="home">${t('guest')} ↗</button>`}</div></section>`)}

function render(){lab?.dispose();lab=null;book.detach();const views={home:landing,chapters:renderChapters,chapter:renderChapter,quiz:renderQuiz,visual:renderVisual,reader:renderReader,progress:renderProgress,settings:renderSettings,account:renderAccount};(views[view]||landing)()}
async function submitAuth(e){e.preventDefault();if(accountBusy)return;const form=new FormData(e.target),username=String(form.get('username')||''),password=String(form.get('password')||'');if(!validUsername(username)){authMessage=t('usernameInvalid');$('#auth-message').textContent=authMessage;return}if(['signup','reset'].includes(authMode)&&(!validPassword(password)||password!==form.get('confirm'))){authMessage=t('passwordInvalid');$('#auth-message').textContent=authMessage;return}accountBusy=true;authMessage='';e.target.querySelector('button[type=submit]').disabled=true;try{if(authMode==='signup'||authMode==='reset'){const result=authMode==='signup'?await account.signup(username,password):await account.reset(username,password,String(form.get('recoveryCode')||''));recoverySecret=result.recoveryCode;recoveryWasReset=authMode==='reset'}else await account.login(username,password)}catch(error){const known=t(error.message);authMessage=known!==error.message?known:pick('Unable to sign in. Check your username and password.','登录未成功，请检查用户名和密码。','Connexion impossible. Vérifiez votre nom et votre mot de passe.')}finally{accountBusy=false;if(view==='account')renderAccount()}}
document.addEventListener('submit',e=>{if(e.target.id==='auth-form')submitAuth(e)});
document.addEventListener('click',async e=>{if(e.target.closest('#guided-lab'))return;const b=e.target.closest('button,a[data-action]');if(!b)return;const d=b.dataset;if(d.view){route(d.view);return}if(d.openChapter){route('chapter',{chapter:d.openChapter});return}if(d.group!==undefined){group=d.group;renderChapters();return}if(d.readChapter){selected=+d.readChapter;bookPage=chapter().start;route('reader',{page:bookPage});return}if(d.readPage){if(view==='reader'){bookPage=+d.readPage;book.render(bookPage);return}route('reader',{page:+d.readPage});return}if(d.language){setLanguage(d.language);data.notes['preferences']={language:d.language,reduceMotion:document.body.classList.contains('reduce-motion'),at:Date.now()};save();render();return}if(d.labId){selected=19;route('visual',{lab:d.labId});return}if(d.switchLab){selected=+d.switchLab;labId=null;route('visual');return}if(d.weakEdge){selected=19;labTab='map';labId=null;route('visual');selectReaction(d.weakEdge);return}if(d.labTab){labTab=d.labTab;renderVisual();return}if(d.option!==undefined&&quiz&&!quiz.checked[quiz.ids[quiz.index]]){quiz.answers[quiz.ids[quiz.index]]=+d.option;saveQuizDraft();document.querySelectorAll('[data-option]').forEach(option=>{const chosen=option.dataset.option===d.option;option.classList.toggle('selected',chosen);option.setAttribute('aria-pressed',String(chosen))});const check=$('[data-action=check-question]');if(check)check.disabled=false;return}if(d.authMode){authMode=d.authMode;authMessage='';renderAccount();return}if(d.reviewQuestion){const q=bank.find(q=>q.id===d.reviewQuestion);selected=q.chapter;quiz={chapter:selected,ids:[q.id],index:0,answers:{},checked:{},started:Date.now()};view='quiz';render();return}if(d.edge){selectReaction(d.edge);return}if(d.revealEdge){const edge=edges.find(x=>x.id===d.revealEdge),answer=$('#edge-detail .edge-answer');if(!answer)return;if(answer.innerHTML){answer.innerHTML='';b.setAttribute('aria-expanded','false');return}data.visual['edge-'+edge.id]={needsReview:true,at:Date.now()};save();b.setAttribute('aria-expanded','true');answer.innerHTML='<p>'+L(edge.condition)+'</p><p>'+L(edge.compatibility)+'</p><div class="reference-line">'+edge.refs.map(p=>'<button class="text-button" data-read-page="'+p+'">'+t('page')+' '+p+' ↗</button>').join('')+'</div>';return}switch(d.action){case'copy-recovery':if(recoverySecret){try{await navigator.clipboard.writeText(recoverySecret);toast(t('copyCode')+' ✓')}catch{toast(t('downloadCode'))}}break;case'download-recovery':if(recoverySecret)download('Organic-Recall-Recovery-Code.txt',recoverySecret+'\n', 'text/plain');break;case'recovery-saved':recoverySecret=null;recoveryWasReset=false;authMode='login';authMessage=t('readyToLogin');renderAccount();break;case'resume-quiz':quiz=null;route('quiz');break;case'open-chapter':route('chapter');break;case'start-quiz':startQuiz();break;case'check-question':checkQuestion();break;case'next-question':nextQuestion();break;case'reader-retry':await book.render(bookPage);break;case'prev-page':await book.render(bookPage-1);break;case'next-page':await book.render(bookPage+1);break;case'go-page':await book.render($('#book-page').value);break;case'bookmark':data.bookmarks['page-'+bookPage]={page:bookPage,chapter:selected,at:Date.now()};data.bookmarks['last-'+selected]={page:bookPage,chapter:selected,at:Date.now()};save();toast(t('bookmark')+' ✓');break;case'export-progress':download('Organic-Recall-Progress-v3.json',JSON.stringify(data,null,2));break;case'restore-progress':$('#progress-file').click();break;case'sync':account.queue(data);await account.flush();break;case'import-guest':data=mergeProgress(data,readLocal('guest'));save();toast(t('restored'));renderProgress();break;case'logout':try{await account.logout()}catch{toast(t('syncError'))}break}});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-chapter-select')){const n=+e.target.value;if(!chapters.some(c=>c.id===n))return;selected=n;labId=null;const chapterUrl=new URL(location.href);chapterUrl.searchParams.set('chapter',selected);chapterUrl.searchParams.delete('task');history.replaceState(null,'',chapterUrl);if(view==='reader'){bookPage=chapter().start;renderReader()}else if(view==='chapter')renderChapter();else if(view==='visual')renderVisual();else if(view==='home')selectSphereChapter(n);return}if(e.target.id==='reaction-select'){selectReaction(e.target.value);return}if(e.target.id==='book-zoom'){book.zoom=Number(e.target.value);book.render(bookPage)}if(e.target.id==='reduce-motion'){document.body.classList.toggle('reduce-motion',e.target.checked);try{localStorage.setItem('or-reduce-motion',e.target.checked?'true':'false')}catch{}}});
document.addEventListener('input',e=>{if(e.target.id==='chapter-search'){query=e.target.value;$('#chapter-grid').innerHTML=chapterCards()}if(e.target.dataset.note){data.notes[e.target.dataset.note]={text:e.target.value,at:Date.now()};save()}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='book-page')book.render(e.target.value);if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-edge]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
$('#progress-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2*1024*1024)throw Error('backup');data=mergeProgress(data,validateBackup(JSON.parse(await file.text())));save();toast(t('restored'));render()}catch{toast(t('backupBad'))}});
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);view=p.get('view')||document.body.dataset.initialView||'account';animateNext=true;selected=+p.get('chapter')||19;bookPage=+p.get('page')||0;labId=p.get('task')||null;render()});
window.addEventListener('online',()=>account.flush());
window.addEventListener('beforeunload',e=>{if(recoverySecret){e.preventDefault();e.returnValue=''}});
async function init(){try{[chapters,bank,translations,chapterTranslations,examTranslations,sectionTranslations]=await Promise.all(['chapters.json','bank.json','content-locale.json','chapter-locale.json','exam-locale.json','section-locale.json'].map(async f=>{const r=await fetch('./'+f);if(!r.ok)throw Error(f);return r.json()}));if(!chapters.some(c=>c.id===selected))selected=19;try{document.body.classList.toggle('reduce-motion',localStorage.getItem('or-reduce-motion')==='true')}catch{}render();await account.init();if(view==='account')renderAccount()}catch{root.innerHTML=`<div class="loading-error"><h1>Organic Recall</h1><p>${t('loadError')}</p></div>`}}
init();
